private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int result = 0;
    while (i < bb.capacity()) {
        if (bb.get(i) >> 7 == 0) {
            result = (bb.get(i) & 0xff);
            sb.append((char) result);
            i++;
        } else if (bb.get(i) >> 5 == 6) {
            result = (bb.get(i) & 0x1f) << 6;
            result |= (bb.get(++i) & 0x3f);
            sb.append((char) result);
        } else if (bb.get(i) >> 4 == 14) {
            result = (bb.get(i) & 0xf) << 12;
            result |= (bb.get(++i) & 0x3f) << 6;
            result |= (bb.get(++i) & 0x3f);
            sb.append((char) result);
        } else {
            result = (bb.get(i) & 0x7) << 18;
            result |= (bb.get(++i) & 0x3f) << 12;
            result |= (bb.get(++i) & 0x3f) << 6;
            result |= (bb.get(++i) & 0x3f);
            sb.append((char) result);
        }
    }
    return i;
}

