private void enlarge(final int size) {
    // Step 1: Check if the addition of 'size' to the current length would overflow
    if (Integer.MAX_VALUE - size < this.length) {
        throw new IllegalStateException("Exceeded maximum capacity");
    }

    // Step 2: Create a new array with the appropriate size
    byte[] newData = new byte[this.length + size];

    // Step 3: Copy the current contents of this vector to the new array
    System.arraycopy(this.data, 0, newData, 0, this.length);

    // Step 4: Update the length of this vector and set the new array as the backing array
    this.length += size;
    this.data = newData;
}

