public void generateGraph(Graph<V,E> target,Map<String,V> resultMap) {
    // check if the map is empty
    if (resultMap.isEmpty()) {
        return;
    }
    // create an array list for the list of vertices
    List<V> vertices = new ArrayList<>();
    // create an iterator for the map
    Iterator<String> iterator = resultMap.keySet().iterator();
    // loop through the map
    while (iterator.hasNext()) {
        // get the next key
        String key = iterator.next();
        // get the corresponding vertex
        V vertex = resultMap.get(key);
        // add the vertex to the list of vertices
        vertices.add(vertex);
    }
    // loop through the list of vertices
    for (int i = 0; i < vertices.size(); i++) {
        // get the current vertex
        V vertex = vertices.get(i);
        // loop through the rest of the list of vertices
        for (int j = i + 1; j < vertices.size(); j++) {
            // get the next vertex
            V nextVertex = vertices.get(j);
            // create a new edge
            E edge = new Edge(vertex, nextVertex);
            // add the edge to the graph
            target.addEdge(edge);
        }
    }
}

