    if (start < 0 || start >= currentFrame.length || end < 0 || end > currentFrame.length || start > end) {
        throw new IllegalArgumentException("start and end indices must be valid and satisfy start <= end");
    }

    for (int i = start; i < end; i++) {
        switch (currentFrame[i]) {
            case OBJECT:
                stackMapTableEntries.add(new Object_type(currentFrame[i]));
                break;
            case ARRAY:
                stackMapTableEntries.add(new ArrayType(currentFrame[i]));
                break;
            case UNINIT:
                stackMapTableEntries.add(new UninitializedType(currentFrame[i]));
