public short readShort(final int offset) {
    try {
        // Check if the offset is valid
        if (offset < 0 || offset > classReader.length - 2) {
            throw new IndexOutOfBoundsException("Invalid offset: " + offset);
        }

        // Read the short value from the class reader
        byte[] bytes = new byte[2];
        classReader.read(offset, bytes);
        int value = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN).getShort();

        return (short) value;
    } catch (IOException e) {
        throw new RuntimeException("Error reading short value at offset " + offset, e);
    }
}

