public final MatchResult match(CharSequence uri) {
    // Check if the URI is null or empty
    if (uri == null || uri.length() == 0) {
        throw new IllegalArgumentException("Uri cannot be null or empty.");
    }

    // Check if the template is null or empty
    if (this.template == null || this.template.length() == 0) {
        throw new IllegalStateException("Template cannot be null or empty.");
    }

    // Initialize the match result
    MatchResult result = new MatchResult();

    // Iterate over the characters of the URI and template
    for (int i = 0; i < uri.length(); i++) {
        char c = uri.charAt(i);
        char t = this.template.charAt(i);

        // Check if the character matches the template
        if (c == t) {
            // Update the match result
            result.update(i, i);
        } else {
            // No match, return null
            return null;
        }
    }

    // Return the match result
    return result;
}

