protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour.isEmpty()) {
        return null;
    }

    List<V> vertices = new ArrayList<>();
    Iterator<E> edges = tour.iterator();
    vertices.add(edges.next().getSource());

    while (edges.hasNext()) {
        E edge = edges.next();
        if (edge.getSource().equals(vertices.get(vertices.size() - 1))) {
            vertices.add(edge.getDestination());
        } else {
            vertices.add(edge.getSource());
        }
    }

    return graph.getPath(vertices);
}

