public boolean unlink(ListNodeImpl<E> node) {
    // Check if the node is not null
    if (node == null) {
        return false;
    }

    // Find the node's predecessor
    ListNodeImpl<E> predecessor = node.getPredecessor();

    // If the node is the head, set the new head
    if (predecessor == null) {
        head = node.getNext();
    } else {
        predecessor.setNext(node.getNext());
    }

    // If the node is the tail, set the new tail
    if (node.getNext() == null) {
        tail = node.getPredecessor();
    } else {
        node.getNext().setPredecessor(node.getPredecessor());
    }

    // Set the node's fields to null
    node.setNext(null);
    node.setPredecessor(null);

    size--;
    return true;
}

public List<SequenceRange> buildSequenceRanges(List<Long> profileIds, int maxNumRanges) {
    List<SequenceRange> sequenceRanges = new ArrayList<>();
    if (profileIds == null || profileIds.isEmpty()) {
        return sequenceRanges;
    }

    // Sort the profile IDs in ascending order
    List<Long> sortedProfileIds = new ArrayList<>(profileIds);
    Collections.sort(sortedProfileIds);

    // Create a range for each consecutive set of profile IDs
    for (int i = 0; i < sortedProfileIds.size() - 1; i++) {
        if (sortedProfileIds.get(i) + 1 == sortedProfileIds.get(i + 1)) {
            continue;
        }
        sequenceRanges.add(new SequenceRange(sortedProfileIds.get(i), sortedProfileIds.get(i + 1)));
        if (sequenceRanges.size() == maxNumRanges) {
            break;
        }
    }

    return sequenceRanges;
}

