private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the given vertices are all contained in the graph
    if (!graph.containsAll(vertices)) {
        throw new IllegalArgumentException("The given vertices are not all contained in the graph");
    }

    // Check if the given vertices form a clique by checking if every edge is present in the graph
    for (V u : vertices) {
        int degreeU = graph.degreeOf(u);
        for (V v : vertices) {
            if (u != v) {
                // Skip self-loops
                if (u.equals(v)) {
                    continue;
                }
                // Check if the edge is present in the graph
                if (!graph.containsEdge(u, v)) {
                    return false;
                }
            }
        }
    }

    // If the code reaches this point, it means that all edges are present in the graph, so the induced subgraph is a clique
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys) {
