}

public void pop(String descriptor) {

    int typeCount = 1;
    if (descriptor.charAt(0) == '(') {
        // Descriptor is a method descriptor, get the number of arguments
        typeCount = descriptor.length() - 1;
    }

    for (int i = 0; i < typeCount; i++) {
        try {
            // Pop the abstract type from the output frame stack
            popFrame();
        } catch (RuntimeException e) {
            // Handle potential runtime issues with exception handling behavior
            System.err.println("Error popping frame: " + e.getMessage());
        }
    }
}

