Edge edgeToNext() {
    // Check if the current node is virtual
    if (isVirtual()) {
        // If the current node is virtual, get its real counterpart
        Node realNode = getRealCounterpart();
        // Get the edge connecting the real node to the next node
        Edge edge = realNode.getNextEdge();
        // If the edge is virtual, get its real counterpart
        if (edge.isVirtual()) {
            edge = edge.getRealCounterpart();
        }
        // Return the real edge connecting the real nodes
        return edge;
    } else {
        // If the current node is not virtual, get its next edge
        Edge edge = getNextEdge();
        // If the edge is virtual, get its real counterpart
        if (edge.isVirtual()) {
            edge = edge.getRealCounterpart();
        }
        // Return the real edge connecting the current node to the next node
        return edge;
    }
}

